      overview: 'Test your understanding of how different stotras target specific psychological states and life challenges.',
      mainContent: `The stotra tradition developed specific hymns for specific psychological states and life circumstances. This isn't superstition but applied psychology -- using acoustic and emotional patterns optimized for particular mental states.

**Fear and Anxiety:** Stotras invoking protective deities (Durga, Kali, Hanuman) use stronger consonants, faster rhythms, and martial imagery. The aggressive sounds and imagery prime the nervous system for action rather than freeze, shifting anxiety into mobilized courage.

**Depression and Lethargy:** Stotras invoking solar deities (Surya) or energizing forms (Shakti) use bright vowels, ascending melodic patterns, and imagery of light and movement. The acoustic qualities literally sound more energizing, helping shift depressive states.

**Grief and Loss:** Stotras invoking Shiva (especially as Nataraja, lord of dance) acknowledge impermanence while affirming the eternal. The philosophical content combined with slow, meditative melodies provides both validation of grief and perspective beyond it.

**Confusion and Decision-Making:** Stotras invoking Saraswati (knowledge) or Ganesha (obstacle removal) use clear, articulated consonants and structured logical progressions in their verses. The clarity of structure provides mental scaffolding when thinking feels muddled.

**Relationship Difficulties:** Stotras invoking divine couples (Radha-Krishna, Shiva-Parvati) model idealized relationship dynamics. The poetry often describes mutual devotion, complementary strengths, and harmonious interaction -- essentially relationship therapy through archetypal example.

This targeted approach means effective practice requires matching the stotra to your current need rather than random selection or always practicing the same hymn. Traditional practitioners often had several stotras in their repertoire, choosing based on current circumstance.

Modern psychology validates this approach. Emotion regulation research shows that different strategies work for different emotional states. Activation strategies help with sadness; calming strategies help with anxiety. The stotra tradition encoded these distinctions in its classification system.

The practice also teaches emotional granularity -- the ability to distinguish between different negative states (anxiety vs. grief, frustration vs. depression). Choosing an appropriate stotra requires first identifying your current state accurately, developing the emotional awareness that itself improves mental health.`,
      keyTakeaway: 'Different stotras target specific psychological states through optimized acoustic patterns, imagery, and philosophical content, requiring matching practice to current needs for maximum effectiveness.',
